/// What a row gives on the jars
#[derive(Debug, PartialEq, Eq, Clone)]
enum Expected {
    /// The bytes `substConstants` returns
    Bytes(&'static str),
    /// A whole tree reduces to `true`
    True,
    /// The evaluation throws
    Error,
    /// The bytes are refused at parse
    Refused,
}
use Expected::{Bytes, Error, Refused, True};

/// A row: its name, the expression's bytes, the tree version, the activated versions it runs
/// at, the jars' outcome, and the jars' cost counter (also at a throw; 0 for a refusal)
type Row = (&'static str, &'static str, u8, &'static [i8], Expected, u64);
/// A whole tree: its name, its bytes, the activated versions, the jars' outcome and the cost
/// of the reduction (0 where there is none)
type TreeRow = (&'static str, &'static str, &'static [i8], Expected, u64);

/// The header of the context: version 5, its fields filled with their own index
const HEADER: &str = "";
/// The self box: a P2PK box without tokens or registers
const SELF_BOX: &str = "c0843d0008cd0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798640000111111111111111111111111111111111111111111111111111111111111111100";

/// The extension of the `source` rows' context, as bytes: variable 1 is `Coll[String]("C")`
const SOURCE_EXTENSION: &str = "01010c66010143";
/// The self box of the `source` rows' context: [`SELF_BOX`] with `Coll[String]("D")` in R4
const SOURCE_SELF_BOX: &str = "c0843d0008cd0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f817986400010c66010144111111111111111111111111111111111111111111111111111111111111111100";

/// What a row reads of the jars' context: one header, a pre-header whose parent is that header,
/// the self box, no context variable. Every other field is arbitrary: no row reads it
fn context(activated: i8) -> Context<'static> {
    context_of(activated, SELF_BOX, None)
}

/// The context of the `source` rows: a `Coll[String]` in context variable 1 and in the self
/// box's R4, each read from bytes as a transaction's and a box's are
fn source_context(activated: i8) -> Context<'static> {
    context_of(activated, SOURCE_SELF_BOX, Some(SOURCE_EXTENSION))
}

fn context_of(activated: i8, self_box: &str, extension: Option<&str>) -> Context<'static> {
    let act = ErgoTreeVersion::from(activated as u8);
    let header_bytes = base16::decode(format!("68{HEADER}").as_bytes()).unwrap();
    let header_const = from_bytes(&header_bytes)
        .with_versions(
            ErgoTreeVersion::V3,
            ErgoTreeVersion::V3,
            Constant::sigma_parse,
        )
        .unwrap();
    let mut header = None;
    if let Literal::Header(h) = header_const.v {
        header = Some(*h);
    }
    let header = header.unwrap();
    let self_box: &'static ErgoBox = Box::leak(Box::new(
        from_bytes(&base16::decode(self_box.as_bytes()).unwrap())
            .with_versions(act, act, ErgoBox::sigma_parse)
            .unwrap(),
    ));
    let extension = match extension {
        Some(hex) => from_bytes(&base16::decode(hex.as_bytes()).unwrap())
            .with_versions(act, act, ContextExtension::sigma_parse)
            .unwrap(),
        None => ContextExtension::empty(),
    };
    let extension: &'static ContextExtension = Box::leak(Box::new(extension));
    let mut pre_header = force_any_val::<PreHeader>();
    pre_header.version = 3;
    pre_header.parent_id = header.id;
    pre_header.height = 100;
    let mut ctx = force_any_val::<Context>();
    ctx.self_box = self_box;
    ctx.extension = extension;
    ctx.headers = ContextHeaders::from_vec(vec![header]).unwrap();
    ctx.pre_header = pre_header;
    ctx.activated_script_version_byte = activated;
    ctx.jit_cost.set(0);
    ctx.jit_cost_limit = Some(10_000_000);
    ctx
}

/// What the fork gives for a row at one activated version, as text (`bytes <hex>`, `error`,
/// `refused`), and the cost counter where it stopped
fn eval_row(
    body: &str,
    version: u8,
    activated: i8,
    ctx: fn(i8) -> Context<'static>,
) -> (String, u64) {
    let bytes = base16::decode(body.as_bytes()).unwrap();
    let tree_version = ErgoTreeVersion::from(version);
    let parsed = from_bytes(&bytes).with_versions(
        ErgoTreeVersion::from(activated as u8),
        tree_version,
        Expr::sigma_parse,
    );
    let Ok(expr) = parsed else {
        return ("refused".into(), 0);
    };
    let ctx = ctx(activated);
    ctx.tree_version.set(tree_version);
    let res = expr.eval(&mut Env::empty(), &ctx).map(|v| v.to_static());
    let cost = ctx.jit_cost_value();
    let got = match res {
        Ok(Value::Coll(CollValue::Bytes(b))) => {
            let b: Vec<u8> = b.iter().map(|x| *x as u8).collect();
            format!("bytes {}", base16::encode_lower(&b))
        }
        Ok(other) => format!("another value: {}", debug_start(&other)),
        Err(_) => "error".into(),
    };
    (got, cost)
}

/// What the fork gives for a whole tree on the node's path, `reduce_to_crypto`, as text
/// (`true`, `error`, `refused`), and the cost of the reduction
fn reduce_row(tree: &str, activated: i8) -> (String, u64) {
    let bytes = base16::decode(tree.as_bytes()).unwrap();
    let parsed = from_bytes(&bytes).with_versions(
        ErgoTreeVersion::from(activated as u8),
        ErgoTreeVersion::V3,
        ErgoTree::sigma_parse,
    );
    let Ok(tree) = parsed else {
        return ("refused".into(), 0);
    };
    match reduce_to_crypto(&tree, &context(activated)) {
        Ok(r) if r.sigma_prop == SigmaBoolean::TrivialProp(true) => ("true".into(), r.cost),
        Ok(r) => (format!("another proposition: {:?}", r.sigma_prop), r.cost),
        Err(_) => ("error".into(), 0),
    }
}

fn text(expected: &Expected) -> String {
    match expected {
        Bytes(hex) => format!("bytes {hex}"),
        True => "true".into(),
        Error => "error".into(),
        Refused => "refused".into(),
    }
}

/// The runs of a table in a context, and those that are not the jars'
fn failures(rows: &[Row], ctx: fn(i8) -> Context<'static>) -> (usize, Vec<String>) {
    let mut runs = 0;
    let mut failed = vec![];
    for (name, body, version, activated, expected, cost) in rows {
        for act in *activated {
            runs += 1;
            let (got, stopped_at) = eval_row(body, *version, *act, ctx);
            if got != text(expected) || stopped_at != *cost {
                failed.push(format!(
                    "{name} at activated {act}: expected {} @{cost}, got {got} @{stopped_at}",
                    text(expected)
                ));
            }
        }
    }
    (runs, failed)
}

fn tree_failures(rows: &[TreeRow]) -> (usize, Vec<String>) {
    let mut runs = 0;
    let mut failed = vec![];
    for (name, tree, activated, expected, cost) in rows {
        for act in *activated {
            runs += 1;
            let (got, got_cost) = reduce_row(tree, *act);
            if got != text(expected) || got_cost != *cost {
                failed.push(format!(
                    "{name} at activated {act}: expected {} @{cost}, got {got} @{got_cost}",
                    text(expected)
                ));
            }
        }
    }
    (runs, failed)
}

// a `Header` below tree version 3 is not lifted, and a `String` from it is not, written or
// not; a `PreHeader` from tree version 3 is lifted, and so is a collection whatever it holds:
// where nothing writes them the script has its bytes
#[test]
fn a_new_value_is_lifted_by_its_class_and_the_tree_version() {
    let (runs, failed) = failures(CHANGED, context);
    assert!(
        failed.is_empty(),
        "{} of {runs} runs: {failed:#?}",
        failed.len()
    );
}

// every other kind, and every other new value that is written
#[test]
fn what_was_sigmastates_lift_stays_so() {
    let (runs, failed) = failures(UNCHANGED, context);
    assert!(
        failed.is_empty(),
        "{} of {runs} runs: {failed:#?}",
        failed.len()
    );
}

// a `String` is not lifted from tree version 3 wherever it comes from: a context variable, a
// register
#[test]
fn a_string_from_a_variable_or_a_register_is_lifted_below_tree_version_3_only() {
    let (runs, failed) = failures(CHANGED_SOURCES, source_context);
    assert!(
        failed.is_empty(),
        "{} of {runs} runs: {failed:#?}",
        failed.len()
    );
    let (runs, failed) = failures(UNCHANGED_SOURCES, source_context);
    assert!(
        failed.is_empty(),
        "{} of {runs} runs: {failed:#?}",
        failed.len()
    );
}

// the node's path: `sigmaProp(substConstants(..).size > 0)` through `reduce_to_crypto`
#[test]
fn a_tree_is_reduced_as_the_jvm_reduces_it() {
    let (runs, failed) = tree_failures(CHANGED_TREES);
    assert!(
        failed.is_empty(),
        "{} of {runs} runs: {failed:#?}",
        failed.len()
    );
}

#[test]
fn a_tree_that_was_reduced_as_the_jvm_reduces_it_stays_so() {
    let (runs, failed) = tree_failures(UNCHANGED_TREES);
    assert!(
        failed.is_empty(),
        "{} of {runs} runs: {failed:#?}",
        failed.len()
    );
}

